      expect(scenario).toMatchObject({
        kind: "tools.call",
        tool: "echo",
        arguments: {
  target.redact = <T>(value: T): T => JSON.parse(JSON.stringify(original(value)).replaceAll("logging.message", "[REDACTED]"));
  const events: any[] = [];
  const client = new McpFnClient({ target, events: event => { events.push(event); } });
  try {
