          requestId: this.redact(requestId, { preserveKeys: false }),
          at,
          target: { ...this.redact(descriptor, { preserveKeys: false }), kind },
          ...(details === undefined
            ? {}
            : { details: this.redact(details, { preserveKeys: false }) }),
        };
      }
    }
